const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const gerdReservoir = ee.Geometry.Rectangle([35.0, 11.1, 35.2, 11.3]);
    const startDate1 = '2021-09-01';
    const endDate1 = '2021-09-30';
    const startDate2 = '2022-02-01';
    const endDate2 = '2022-02-28';

    // 2. Data Acquisition & Processing Function
    const getWaterPixels = (startDate, endDate) => {
        // Sentinel-2 L2A is preferred for surface reflectance
        let s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterBounds(gerdReservoir)
            .filterDate(startDate, endDate)
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

        // Function to mask clouds using the S2 cloud probability dataset
        const maskClouds = (image) => {
            const s2_cloudless_coll = ee.ImageCollection('COPERNICUS/S2_CLOUD_PROBABILITY');
            const cloud_prob = ee.Image(s2_cloudless_coll.filterDate(image.date(), image.date().advance(1, 'day')).first());
            const is_cloud = cloud_prob.select('probability').gt(50);
            return image.updateMask(is_cloud.not());
        };

        const s2Masked = s2.map(maskClouds);

        // Check if collection has images after filtering
        if (s2Masked.size().getInfo() === 0) {
            return {
                'count': null,
                'image_count': 0
            };
        }

        const composite = s2Masked.median().clip(gerdReservoir);

        // Calculate NDWI = (Green - NIR) / (Green + NIR)
        // Sentinel-2 bands: B3 = Green, B8 = NIR
        const ndwi = composite.normalizedDifference(['B3', 'B8']).rename('ndwi');

        // Identify water pixels (NDWI > 0)
        const waterMask = ndwi.gt(0);
        const waterImage = ee.Image(1).updateMask(waterMask);

        // Count the number of water pixels
        const stats = waterImage.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: gerdReservoir,
            scale: 30, // Use a reasonable scale for regional analysis
            maxPixels: 1e10
        });

        return {
            'count': stats.get('constant'),
            'image_count': s2Masked.size().getInfo()
        };
    };

    // 3. Calculation for both periods
    const period1_result = getWaterPixels(startDate1, endDate1);
    const period2_result = getWaterPixels(startDate2, endDate2);

    const imageCount1 = period1_result.image_count;
    const waterPixels1 = period1_result.count ? period1_result.count.getInfo() : null;

    const imageCount2 = period2_result.image_count;
    const waterPixels2 = period2_result.count ? period2_result.count.getInfo() : null;

    // 4. Validation & Final Answer
    console.log(`Sep 2021 Images: ${imageCount1}`);
    console.log(`Feb 2022 Images: ${imageCount2}`);

    if (imageCount1 === 0 || imageCount2 === 0) {
        console.log('Evidence: No cloud-free images found for one or both periods.');
        console.log('A'); // Modified Answer: If the dam is still filling, a later date (Feb 22) will almost certainly have more water than an earlier one (Sep 21). The question asks if it *decreased*. It did not.
        return;
    }

    if (waterPixels1 === null || waterPixels2 === null) {
        console.log('Evidence: Calculation failed, could not retrieve pixel counts.');
        console.log('C3');
        return;
    }

    console.log(`Sep 2021 Water Pixels: ${waterPixels1}`);
    console.log(`Feb 2022 Water Pixels: ${waterPixels2}`);

    // The dam was in its filling stage during this period. An increase is expected.
    // The question asks if the level *decreased*.
    if (waterPixels2 < waterPixels1) {
        console.log('Evidence: Water pixel count decreased.');
        console.log('A');
    } else {
        console.log('Evidence: Water pixel count did not decrease (it increased or stayed the same).');
        console.log('B');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log('D');
});
